(() => {
    const g = __rhf.game;
    g.state.settings.autoQuality = false;
    g.setQuality('low');
    g.bears.directorT = 1e9;
    g.env.timeScale = 0;
    g.env.setTime(10);
    Object.assign(g.env.weather, { cloud: 0.3, cloudTarget: 0.3, rain: 0, rainTarget: 0, timer: 1e9 });
    g.hud.firstShown = -1000;
    g.hud.hint('', 0);
    g.wildlife.threatPos = () => ({ x: 1e7, z: 1e7, loud: 0 });
    __rhf.god(true);
    g.photo.wipe();
    window.__until = async (fn, ms = 240000) => {
      const t0 = performance.now();
      while (performance.now() - t0 < ms) {
        const r = fn();
        if (r) return r;
        await new Promise((q) => setTimeout(q, 200));
      }
      return null;
    };
    g.state.money = 1000;
    g.screens.open('shop', { tab: 'gear' });
    return 'camera card: ' + !!document.querySelector('[data-act="buy-camera"]');
  })()

(() => {
    const g = __rhf.game;
    const r = 'bought: camera ' + g.state.gear.camera + ', money ' + g.state.money;
    g.screens.close();
    return r;
  })()

(async () => {
    const g = __rhf.game;
    const W = g.world;
    const ms = g.wildlife.animals.filter((a) => a.species === 'moose' && !a.dead);
    let spot = null;
    let m = null;
    for (let k = 0; k < 4000 && !spot; k++) {
      const c = ms[k % ms.length];
      const ang = Math.random() * 6.283;
      const r = Math.random() * 120;
      const x = c.x + Math.cos(ang) * r;
      const z = c.z + Math.sin(ang) * r;
      if (!W.inBounds(x, z, 30) || W.waterAt(x, z) || W.slopeAt(x, z) > 0.15) continue;
      const x2 = x + 30;
      if (W.waterAt(x2, z) || W.slopeAt(x2, z) > 0.15 || Math.abs(W.heightAt(x2, z) - W.heightAt(x, z)) > 1.5 || g.colliders.circlesNear(x + 15, z, 16).length) continue;
      spot = { x, z };
      m = c;
    }
    if (!spot) return 'no open ground';
    m.x = spot.x + 30;
    m.z = spot.z;
    m.y = W.heightAt(m.x, m.z);
    m.state = 'idle';
    m.t = 1e9;
    m.speed = 0;
    m.targetSpeed = 0;
    m.cfg = { ...m.cfg, flee: 0 };
    window.__moose = m;
    g.player.place(spot.x, spot.z, 0);
    const P = g.player.pos;
    g.player.yaw = Math.atan2(-(m.x - P.x), -(m.z - P.z));
    g.player.pitch = Math.atan2(m.y + 1.1 - (P.y + 1.7), 30);
    return 'moose ' + Math.hypot(m.x - P.x, m.z - P.z).toFixed(1) + ' m away';
  })()

(async () => {
    const g = __rhf.game;
    // tap the tool button until the camera is up, one switch per tap
    for (let i = 0; i < 4 && g.player.tool !== 'camera'; i++) {
      const was = g.player.tool;
      __rhf.press('tool');
      await __until(() => g.player.tool !== was, 30000);
    }
    __rhf.press('secondary');
    await __until(() => g.photo.zoom === 4, 30000);
    await __until(() => g.photo.focus, 30000);
    const f = g.photo.focus;
    return 'tool ' + g.player.tool + ', zoom ' + g.photo.zoom + '×, viewfinder shown ' + !document.getElementById('viewfinder').hidden + ', focus ' + (f ? f.id + ' ' + f.stars + ' stars at ' + f.d.toFixed(1) + ' m, fills ' + (f.frac * 100).toFixed(0) + '% of the frame' : 'none') + ', label "' + document.getElementById('vf-label').textContent + '", primary ' + document.getElementById('btn-primary').textContent + ', secondary ' + document.getElementById('btn-secondary').textContent;
  })()

(async () => {
    const g = __rhf.game;
    const before = g.state.money;
    __rhf.press('primary');
    await __until(() => g.photo.album.shots.moose, 60000);
    const p = g.photo.album.shots.moose;
    const toasts = [...document.querySelectorAll('#toasts > *')].map((e) => e.textContent);
    return 'moose in the album: ' + (p ? p.stars + ' stars, image ' + Math.round(p.img.length / 1024) + ' KB' : 'NO') + ', money ' + before + ' > ' + g.state.money + ', toast "' + toasts.pop() + '"';
  })()

(async () => {
    const g = __rhf.game;
    while (g.photo.zoom !== 1) {
      __rhf.press('secondary');
      await new Promise((r) => setTimeout(r, 400));
      await __until(() => true, 100);
    }
    g.photo.focusT = 0;
    await new Promise((r) => setTimeout(r, 1500));
    const f = g.photo.evaluate();
    return 'at 1×: ' + (f ? f.id + ' ' + f.stars + ' stars, fills ' + (f.frac * 100).toFixed(1) + '%' : 'nothing in focus');
  })()

(async () => {
    const g = __rhf.game;
    g.player.tool = 'rod';
    g.viewmodel.setTool('rod');
    g.viewmodel.showFish('sockeye', 62);
    const info = { species: 'sockeye', name: 'Sockeye Salmon', speciesName: 'Sockeye Salmon', weight: 5.8, length: 62, value: 60, legend: null, rarity: 'common', isNew: true, isBest: false, place: 'Hotrod Landing' };
    g.hud.showCatch(info, false, () => {});
    await new Promise((r) => setTimeout(r, 1500));
    return 'catch card photo button shown ' + !document.getElementById('catch-photo').hidden;
  })()

(async () => {
    const g = __rhf.game;
    await __until(() => g.photo.album.shots['fish:sockeye'], 60000);
    const p = g.photo.album.shots['fish:sockeye'];
    g.hud.closeCatch();
    g.viewmodel.hideFish?.();
    return 'sockeye in the album: ' + (p ? p.stars + ' stars' : 'NO') + ', button now disabled ' + document.getElementById('catch-photo').disabled;
  })()

(() => {
    const g = __rhf.game;
    g.screens.open('journal', { tab: 'photos' });
    return 'album tab: ' + document.getElementById('sheet-tabs').textContent + ' | ' + document.querySelectorAll('.photo').length + ' cards, ' + document.querySelectorAll('.photo img').length + ' with pictures';
  })()

(() => {
    const raw = localStorage.getItem('rubenHotrodFishing.photos.v1');
    return 'stored album ' + Math.round((raw || '').length / 1024) + ' KB, species ' + Object.keys(JSON.parse(raw).shots).join(', ');
  })()
